using System;using System.Linq;using Game.Components;using Unity.Entities;using Unity.Mathematics;using Newtonsoft.Json.Linq;
namespace Game.Runtime {
internal sealed class SourceS003PlayerPlacementSession {
 readonly EntityManager em;readonly Entity session,grid,bank;readonly string attemptIdentity;readonly float sourceBuildPlane;readonly SourceGuardTowerPlacementValidation validation;readonly RuntimeDefinition tower;readonly GeneratedBuildingRegistration registration;bool diagnosticCommandRecorded,diagnosticValidCommandRecorded;SourceHostPlacementLifecycle.PlacementState pendingPlayerPreview;int pendingPlayerTransaction;readonly SourcePlayerConstructionReservation reservation;readonly SourceHostPlacementLifecycle lifecycle=new SourceHostPlacementLifecycle();readonly SourceHostPlacementSession sourceSession=new SourceHostPlacementSession();
 internal SourceS003PlayerPlacementSession(EntityManager em,Entity session,Entity grid,Entity bank,RuntimeDefinition tower,SourceGuardTowerPlacementValidation validation,GeneratedBuildingRegistration registration,float sourceBuildPlane){this.sourceBuildPlane=sourceBuildPlane;this.registration=registration??throw new ArgumentNullException(nameof(registration));this.validation=validation??throw new ArgumentNullException(nameof(validation));this.em=em??throw new ArgumentNullException(nameof(em));this.session=session;this.grid=grid;this.bank=bank;this.tower=tower;if(!em.Exists(session)||!em.Exists(grid)||!em.HasComponent<GridConfig>(grid)||!em.HasBuffer<GridRoad>(grid)||!em.HasComponent<DynamicBlockerComponent>(grid)||tower==null||!tower.SourceMetadataComplete||tower.Prefab?.name!="Building_GuardTower"||tower.HasRunway||tower.IsWall)throw new NotSupportedException("Actual S003 source session/grid/ordinary guard tower required");SourceGroundMissionFamily.RequireSession(em,session,true);attemptIdentity=em.GetComponentData<SkirmishMatchState>(session).SessionId.ToString();reservation=new SourcePlayerConstructionReservation(new SourceCampResourceReads(em,bank));}
 // The initial value state comes from the same source owner as native Begin;
 // it is not a validated preview, touch target, or placement grant.
 internal SourceHostPlacementLifecycle.PlacementState CreateSourceInitialState(Vector2Int resolvedOrigin){var initial=BuildingPlacementInitialPreviewState.FromResolvedOrigin(resolvedOrigin);return new SourceHostPlacementLifecycle.PlacementState{Definition=tower,IsValid=false,OriginCell=initial.OriginCell,CommittedOriginCell=initial.CommittedOriginCell,DragStartOriginCell=initial.DragStartOriginCell,DragCurrentOriginCell=initial.DragCurrentOriginCell,AutoRotateVertical=initial.AutoRotateVertical,HideCurrentWallPreview=initial.HideCurrentWallPreview};}
 internal JObject DiagnosticCandidateState(float3 worldPoint){if(!Unity.Mathematics.math.all(Unity.Mathematics.math.isfinite(worldPoint)))throw new ArgumentException("Finite public site required");var g=em.GetComponentData<GridConfig>(grid);var cell=GridUtils.WorldToCell(g,worldPoint);if(!GridUtils.InBounds(cell,g.Width,g.Height))return new JObject{["candidate_in_grid"]=false,["preview_bound"]=false};var origin=BuildingPlacementInitialPreviewState.CenterCellToOrigin(new Vector2Int(cell.x,cell.y),tower.FootprintCells);var initial=CreateSourceInitialState(origin);string validity;try{validity=validation.IsPlacementValid(tower,origin,tower.FootprintCells,false)?"PassesCapturedGeometryDiagnostic":"RejectedByCapturedGeometryDiagnostic";}catch(NotSupportedException e){validity="Unknown_"+e.Message;}return new JObject{["candidate_in_grid"]=true,["center_cell"]=new JArray(cell.x,cell.y),["origin"]=new JArray(initial.OriginCell.x,initial.OriginCell.y),["preview_bound"]=false,["touch_reachability_known"]=false,["active_water_qualified"]=false,["placement_validity_known"]=false,["diagnostic_geometry_result"]=validity};}
 internal JObject DiagnosticPointerState(SourceS002NumericCameraProvider camera,float3 screen){var g=em.GetComponentData<GridConfig>(grid);if(camera==null||!camera.TryDiagnosticPointerCell(screen,g,sourceBuildPlane,out var center))return new JObject{["ray_hits_grid"]=false,["native_touch_observed"]=false,["camera_qualified"]=false};var origin=BuildingPlacementInitialPreviewState.CenterCellToOrigin(center,tower.FootprintCells);var state=CreateSourceInitialState(origin);string result;try{state.IsValid=validation.IsPlacementValid(tower,origin,tower.FootprintCells,false);result=state.IsValid?"PassesCapturedGeometryDiagnostic":"RejectedByCapturedGeometryDiagnostic";}catch(NotSupportedException e){result="Unknown_"+e.Message;}return new JObject{["ray_hits_grid"]=true,["center_cell"]=new JArray(center.x,center.y),["origin"]=new JArray(state.OriginCell.x,state.OriginCell.y),["geometry_result"]=result,["native_touch_observed"]=false,["camera_qualified"]=false,["active_water_qualified"]=false,["placement_qualified"]=false};}
 internal bool DiagnosticOpen=>lifecycle.ActivePlacement!=null;
 internal bool DiagnosticValid=>DiagnosticOpen&&lifecycle.ActivePlacement.IsValid;
 internal JObject OpenDiagnostic(SourceS002NumericCameraProvider camera){if(DiagnosticOpen)throw new InvalidOperationException("Preview already open");if(!camera.TryDiagnosticPointerCell(new float3(640,360,0),em.GetComponentData<GridConfig>(grid),sourceBuildPlane,out var center))throw new NotSupportedException("Actual diagnostic camera center ray misses grid");var origin=BuildingPlacementInitialPreviewState.CenterCellToOrigin(center,tower.FootprintCells);lifecycle.ActivePlacement=CreateSourceInitialState(origin);lifecycle.ActivePlacement.IsValid=validation.IsPlacementValid(tower,origin,tower.FootprintCells,false);return new JObject{["source_preview_open"]=true,["preview_qualified"]=false,["native_touch_observed"]=false};}
 internal JObject MoveDiagnostic(SourceS002NumericCameraProvider camera,float3 screen){if(!DiagnosticOpen)throw new InvalidOperationException("Active source preview required");if(!camera.TryDiagnosticPointerCell(screen,em.GetComponentData<GridConfig>(grid),sourceBuildPlane,out var center))return new JObject{["accepted"]=false,["reason"]="RayMissesGrid"};var origin=BuildingPlacementInitialPreviewState.CenterCellToOrigin(center,tower.FootprintCells);var active=lifecycle.ActivePlacement;active.ApplyHover(origin);active.IsValid=validation.IsPlacementValid(tower,origin,tower.FootprintCells,false);return new JObject{["source_preview_moved"]=true,["origin"]=new JArray(origin.x,origin.y),["captured_geometry_valid"]=lifecycle.ActivePlacement.IsValid,["native_touch_observed"]=false};}
 internal JObject CancelDiagnostic(){if(!DiagnosticOpen)throw new InvalidOperationException("Active source preview required");lifecycle.ActivePlacement=null;return new JObject{["source_preview_cancelled"]=true,["native_touch_observed"]=false};}
 internal JObject ConfirmDiagnostic(int id){if(!DiagnosticOpen)throw new InvalidOperationException("Active source preview required");var p=lifecycle.ActivePlacement;pendingPlayerPreview=p;pendingPlayerTransaction=id;RuntimeBuildingEntity created=null;var ctx=new SourceHostPlacementLifecycle.ConfirmContext{ValidateConfirm=x=>ReferenceEquals(x,p)&&validation.IsPlacementValid(tower,x.OriginCell,tower.FootprintCells,false),TryReserveCost=reservation.TryReserve,FinalizeCost=reservation.TryFinalize,RollbackCost=reservation.TryRollback,CommitPlacement=x=>{var permit=SourceCanonicalPlayerBirthPermit.Issue(this,em,grid,bank,registration,tower,x.OriginCell,id);created=registration.RegisterAtLegalOrigin(tower,x.OriginCell,playerPermit:permit);if(created!=null){registration.SetOwner(created,em.GetComponentData<FactionEconomy>(bank).FactionId);if(!SkirmishScenarioSpawnSystem.AdoptConstructedBuilding(em,created.CombatEntity,tower.Prefab.name))throw new NotSupportedException("Original player building adoption rejected");}return new SourceHostPlacementCommit.CommitOutcome(created,created!=null?1:0,1);}};try{bool accepted=sourceSession.ConfirmBuildingPlacement(new SourceHostPlacementSession.Context{LifecycleSystem=lifecycle,CreateConfirmContext=()=>ctx,ExitBuildMode=_=>lifecycle.ActivePlacement=null},id,out var reason);return new JObject{["accepted"]=accepted,["reason"]=reason.ToString(),["runtime_building_id"]=created?.Id,["native_touch_observed"]=false,["preview_qualified"]=false};}finally{pendingPlayerPreview=null;pendingPlayerTransaction=0;}}
 internal bool AttestPlayerBirth(EntityManager manager,Entity requestedGrid,Entity requestedBank,GeneratedBuildingRegistration factory,RuntimeDefinition definition,Vector2Int origin,int transactionId){return ReferenceEquals(em,manager)&&grid==requestedGrid&&bank==requestedBank&&ReferenceEquals(registration,factory)&&ReferenceEquals(tower,definition)&&ReferenceEquals(lifecycle.ActivePlacement,pendingPlayerPreview)&&pendingPlayerPreview!=null&&pendingPlayerPreview.IsValid&&ReferenceEquals(pendingPlayerPreview.Definition,definition)&&pendingPlayerPreview.OriginCell==origin&&pendingPlayerPreview.CommittedOriginCell==origin&&pendingPlayerTransaction==transactionId&&reservation.IsActiveFor(manager,bank,transactionId)&&em.Exists(session)&&em.Exists(grid)&&em.Exists(bank)&&CurrentSessionAndPlacement(origin);}
 bool CurrentSessionAndPlacement(Vector2Int origin){SourceGroundMissionFamily.RequireSession(em,session,true);var match=em.GetComponentData<SkirmishMatchState>(session);return match.SessionId.ToString()==attemptIdentity&&match.Phase==SkirmishPhase.Playing&&validation.IsPlacementValid(tower,origin,tower.FootprintCells,false);}
 internal bool HasActualPreview=>lifecycle.ActivePlacement!=null;
 // No placeholder preview is constructed. The real source preview and player
 // factory must bind their callbacks before the original confirm transaction is invoked.
 internal string MissingAuthority=>"OriginalPreview_PlayerBirth_ActiveWater_TouchHitTesting";
 internal bool ConfirmActualPreview(int transactionId,SourceHostPlacementLifecycle.ConfirmContext context,Action recordBuildingBuilt,Action notifyMinimap,Action<bool> exitBuildMode,out SourceHostPlacementLifecycle.ConfirmFailureReason reason){if(!HasActualPreview||context.ValidateConfirm==null||context.CommitPlacement==null||exitBuildMode==null)throw new NotSupportedException("Actual preview and player factory owners required");context.TryReserveCost=reservation.TryReserve;context.FinalizeCost=reservation.TryFinalize;context.RollbackCost=reservation.TryRollback;return sourceSession.ConfirmBuildingPlacement(new SourceHostPlacementSession.Context{LifecycleSystem=lifecycle,CreateConfirmContext=()=>context,RecordBuildingBuilt=recordBuildingBuilt,NotifyStaticMinimapChanged=notifyMinimap,ExitBuildMode=exitBuildMode},transactionId,out reason);}
}
internal sealed partial class AutonomousWorld {internal SourceGuardTowerPlacementValidation S003DiagnosticPlacementValidation{get;private set;}internal SourceS003PlayerPlacementSession S003PlayerPlacement{get;private set;}internal void BindS003PlayerPlacement(){if(Setup?.CatalogId!="S003"||S003PlayerPlacement!=null)throw new NotSupportedException("Exact one-time S003 placement binding required");Entity bank=Entity.Null;using(var q=Entities.CreateEntityQuery(typeof(FactionEconomy),typeof(FactionTacticalMaterialsComponent)))using(var rows=q.ToEntityArray(Unity.Collections.Allocator.Temp))foreach(var e in rows){if(!FactionIdentity.IsPlayerControlled(Entities.GetComponentData<FactionEconomy>(e).FactionId))continue;if(bank!=Entity.Null)throw new NotSupportedException("Unique player source bank required");bank=e;}var towers=SourceDefinitions.Definitions.Where(d=>d?.Prefab?.name=="Building_GuardTower").ToArray();if(bank==Entity.Null||towers.Length!=1)throw new NotSupportedException("Actual player bank/guard tower required");S003PlayerPlacement=new SourceS003PlayerPlacementSession(Entities,Session,GridEntity,bank,towers[0],S003DiagnosticPlacementValidation,StartingPipeline.ActualRegistration,generatedBuildPlane);}}
}
